func (n *node) applyTrailingSlashRedirect(c *Context) {
	n.prepareRedirectPath(c)
	n.applyForwardedPrefix(c)
	n.toggleTrailingSlash()
	if n.redirectNeedsSlash() && !strings.HasSuffix(n.redirectPath, "/") {
		n.redirectPath += "/"
	}
	n.assignRedirectTarget(n.redirectPath)
	n.commitRedirect(c)
}

func (n *node) lookupFixedPathRedirect(c *Context, trailingSlash bool) bool {
	req := c.Request
	n.redirectPath = req.URL.Path
	n.redirectSlash = trailingSlash
	cleaned := n.canonicalPath(n.redirectPath)
	fixedPath, ok := n.findCaseInsensitivePath(cleaned, n.redirectSlash)
	if !ok {
		return false
	}
	n.assignRedirectTarget(bytesAsString(fixedPath))
	req.URL.Path = n.redirectURL
	n.commitRedirect(c)
	return true
}

