package gin

import (
	"net/http"
	"net/http/httptest"
	"testing"
)

func TestTmpIssueRepro(t *testing.T) {
	r := New()
	r.RedirectTrailingSlash = false
	r.RedirectFixedPath = true
	r.GET("/ping", func(c *Context) { c.String(200, "pong") })

	w := httptest.NewRecorder()
	r.ServeHTTP(w, httptest.NewRequest("GET", "/ping/", nil))
	if w.Code != http.StatusNotFound {
		t.Errorf("expected 404 for /ping/ with RedirectTrailingSlash=false, got %d loc=%q", w.Code, w.Header().Get("Location"))
	}

	w2 := httptest.NewRecorder()
	r.ServeHTTP(w2, httptest.NewRequest("GET", "/PING", nil))
	if w2.Code != http.StatusMovedPermanently || w2.Header().Get("Location") != "/ping" {
		t.Errorf("expected 301 -> /ping for /PING, got %d loc=%q", w2.Code, w2.Header().Get("Location"))
	}

	r2 := New()
	r2.GET("/hello/:name/123", func(c *Context) {})
	r2.GET("/hello/:name/234", func(c *Context) {})

	w3 := httptest.NewRecorder()
	r2.ServeHTTP(w3, httptest.NewRequest("GET", "/hello/abx/", nil))
	if w3.Code != http.StatusMovedPermanently || w3.Header().Get("Location") != "/hello/abx" {
		t.Errorf("expected 301 -> /hello/abx for /hello/abx/, got %d loc=%q", w3.Code, w3.Header().Get("Location"))
	}
}

